/* Round V5 UI. Shared local state, contextual inspection, no external-world automation. */
(function(){'use strict';
const C=window.Round5,Art=window.RoundArt5,{i,avatar,badge,glyph,colors}=Art,$=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dialog=$('#dialog'),picker=$('#picker');let s,storage=true;try{s=JSON.parse(localStorage.getItem(C.KEY));if(!C.valid(s))s=C.seed()}catch(e){s=C.seed();storage=false}
let page='find',filters={activity:'',family:'',travel:15,pace:'',free:false,access:false,duration:0},all=false,stack=[],draft=null,filterDraft=null,queueDraft=[],pop=null,lastFocus=null,toastTimer,collection='All',youTab='Collection',profileTab='Card',lastAwards=[],lastMinute=-1;
const copy=x=>JSON.parse(JSON.stringify(x));
function save(){try{localStorage.setItem(C.KEY,JSON.stringify(s))}catch(e){storage=false}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4300)}
function act(type,data={},draw=true){try{const result=C.run(s,type,data);s=result.state;save();if(draw)render();return result}catch(e){toast(e.message);return null}}
function person(id){if(id==='me')return {id,name:'Jamie',tone:s.tone,hat:s.hat,record:s.record,bio:'Cards, coffee, and whatever happens next.',pace:'Casual'};return C.people[id]||{id,name:'Demo guest',tone:2,hat:'none',record:{rounds:0,types:0,repeat:0},bio:'A sample account added by the demo controls.',pace:'Newcomer'}}
function char(id,wear){const p=person(id);return avatar(p.tone,p.hat,wear??(id==='me'&&s.wear!=='none'?C.R(s.wear).wear:'none'))}
function face(id,click=false){const p=person(id);return `<${click?'button':'span'} class="face c${p.tone}" ${click?`data-action="inspect" data-id="${id}" aria-label="Inspect ${esc(p.name)}"`:'aria-hidden="true"'}>${char(id,'none')}</${click?'button':'span'}>`}
function b(text,action,id='',cls=''){return `<button class="btn ${cls}" data-action="${action}" data-id="${esc(id)}">${text}</button>`}
function title(h,p,extra=''){return `<div class="heading"><div class="headrow"><div><div class="eyebrow">LESS PLANNING. MORE POSSIBILITY.</div><h1>${h}</h1><p>${p}</p></div>${extra}</div></div>`}
function nav(){return [['find','Find a group','now'],['group','Your group','people'],['people','People','chat'],['you','You','you']].map(([id,name,ico])=>`<button class="${page===id?'active':''}" data-action="nav" data-id="${id}" ${page===id?'aria-current="page"':''}>${i(ico)}<span>${name}${id==='group'&&(s.active||s.pending)?' ·':''}</span></button>`).join('')}
function go(id){closeAll();page=id;render();window.scrollTo({top:0,behavior:'instant'})}
function render(){C.sync(s);$('#topnav').innerHTML=nav();$('#bottomnav').innerHTML=nav();$('#self').innerHTML=char('me');$('#main').innerHTML=({find:findView,group:groupView,people:peopleView,you:youView}[page])();rail();if(page==='find')drawList();if(page==='group')drawMessages();save()}
function findView(){return `${title('Good company. No big plan.','Your kind of thing. Right around here.',b(i('plus')+'<span>Start a group</span>','create','','primary'))}${s.active||s.pending?`<div class="inline-state"><span>${s.active?'Your group is waiting.':'Your request has its own place to land.'}</span><button class="textbtn" data-action="nav" data-id="group">Open ${i('arrow')}</button></div>`:''}<div class="finderbar"><button class="filter-control" data-action="choose-filter-activity" aria-haspopup="dialog" aria-expanded="false">${i('now')}<span class="grow"><small>WHAT SOUNDS GOOD?</small><strong>${filters.activity?C.A(filters.activity).name:filters.family||'All activities'}</strong></span>${i('down')}</button><span class="divider"></span><button class="filter-control minor" data-action="choose-travel" aria-haspopup="dialog" aria-expanded="false"><span class="grow"><small>CLOSE ENOUGH</small><strong>${filters.travel}-min walk</strong></span>${i('down')}</button><button class="iconbtn" data-action="filters" aria-label="Refine pace, cost, access, and total time">${i('filter')}</button></div><div class="finder-caption"><span><span class="status-dot"></span>Starting as groups fill · nearby now</span><button class="textbtn" data-action="quickmatch">Find me a fit ${i('spark')}</button></div><div class="tabs" aria-label="Quick activity filters">${['','Games','Sports','Coffee & food','Conversation','Outside'].map(f=>`<button class="chip ${filters.family===f&&!filters.activity?'on':''}" data-action="family" data-id="${esc(f)}" aria-pressed="${filters.family===f&&!filters.activity}">${f||'Everything'}</button>`).join('')}</div><div id="results" aria-live="polite"></div><div class="endline">No events to plan. No feed to keep up with.<br>All people, travel estimates, and places here are fictional.</div>`}
function drawList(){if(!$('#results'))return;const list=C.list(s,filters),visible=all?list:list.slice(0,6),stale=s.groups.every(g=>g.closes<=C.now(s));$('#results').innerHTML=`${s.queue?`<div class="inline-state"><span>Open to ${s.queue.ids.map(id=>C.A(id).name).join(', ')}<br><small class="muted">Private demo interest · ${Math.max(0,Math.ceil((s.queue.until-C.now(s))/60000))} min remaining</small></span><button class="iconbtn" data-action="stopQueue" aria-label="Stop availability">${i('close')}</button></div>`:''}<div class="sectionhead"><h3>${list.length} ${list.length===1?'group':'groups'} with room for you</h3><span>Activity → people → go</span></div>${list.length?`<div class="group-list">${visible.map(groupRow).join('')}</div>${list.length>visible.length?b('See '+(list.length-visible.length)+' more groups '+i('down'),'more','','full gap-sm'):''}`:`<div class="empty">${i('now')}<h3>${stale?'Time for fresh example groups.':'No matching group just yet.'}</h3><p>${stale?'The fictional invitation window ended. Refresh only the sample listings; your character and collection stay yours.':'No unrelated substitutes. Start your thing, change a filter, or open a short availability window.'}</p>${b(stale?'Refresh sample groups':'Start this activity',stale?'refresh':'create','','primary')} ${b('Clear filters','clear','','quiet')}<button class="textbtn" data-action="queue">Keep my options open ${i('arrow')}</button></div>`}${s.groups.every(g=>g.phase==='expired'||g.phase==='canceled')?'<div class="notice gap">The sample window ended. <button class="textbtn" data-action="reset">Restart fictional demo</button></div>':''}`}
function groupRow(g,index){const a=C.A(g.a),v=C.V(g.venue),open=g.cap-C.members(g),fmt=C.F(g);return `<article class="group-row ${index===0?'featured':''}" data-group="${g.id}">${glyph(a)}<div class="group-copy"><h3>${esc(a.name)}${a.formats.length>1?' <span class="small muted">· '+esc(fmt.name)+'</span>':''}</h3><p class="sub">${esc(v.name)} · ${v.eta}-min walk · ${a.minutes} min together</p><p class="note">${esc(g.note)}</p><div class="roster-mini">${g.members.slice(0,3).map(id=>face(id,true)).join('')}${g.members.length>3?`<span class="face small">+${g.members.length-3}</span>`:''}${g.guests?`<span class="face small" title="Host-reported companions">+${g.guests}</span>`:''}<span class="open-face" aria-hidden="true">+</span><span class="count"><b>${C.members(g)} / ${g.cap}</b> going${g.guests?'*':''}</span></div><div class="fill-meter"><span style="width:${C.members(g)/g.cap*100}%"></span></div></div><div class="group-right"><span class="tag">${open===1?'You could be the '+(g.cap===4?'fourth':'last one'):open+' open spots'}</span>${b((g.mode==='request'?'Ask to join':'View group')+' '+i('arrow'),'detail',g.id,index===0?'primary':'')}<span class="small muted" style="font-size:10px">${a.paid?'Pay your own':'Free to join'}${g.mode==='request'?' · requests':''}</span></div></article>`}
function rail(){const g=C.G(s);$('#rail').innerHTML=g?`<div class="rail-card"><span class="rail-title">${i('people')} YOUR NEXT GOOD THING</span><div class="rail-art">${g.members.slice(0,2).map(id=>char(id)).join('')}</div><h2>${esc(C.A(g.a).name)}</h2><p>${C.members(g)}/${g.cap} going · ${esc(C.V(g.venue).name)}<br>${g.phase==='forming'?'Waiting for the format to fill.':g.phase==='complete'?'A sample experience, saved.':'One group. One clear plan.'}</p>${b('Open your group '+i('arrow'),'nav','group','dark')}</div>`:`<div class="rail-card"><span class="rail-title">${i('people')} ALREADY WITH FRIENDS?</span><div class="rail-art">${char('p0')}${char('p1')}<span class="blank-seat">+</span></div><h2>Keep your crew.<br>Fill the gap.</h2><p>Two for tennis. Four for cards. Ten for a game of 5-a-side. The activity knows what it needs.</p>${b('Open the missing spots '+i('plus'),'create-friends','','dark')}</div>`;const r=C.R(s.earned.includes('rally')?'table':'rally');$('#rail').innerHTML+=`<button class="quest" data-action="reward" data-id="${r.id}"><div class="eyebrow">YOUR NEXT LITTLE STORY</div><div class="row gap-sm">${badge(r)}<div><h3>${r.name}</h3><p>${r.id==='rally'?'One more pickleball round.<br>No winning required.':'A familiar place at the table.'}</p></div></div><div class="meter"><span style="width:${Math.min(100,C.metric(s,r)/r.goal*100)}%"></span></div><div class="row between small muted gap-sm"><span>${Math.min(r.goal,C.metric(s,r))}/${r.goal} rounds</span><span>+${r.ap} AP</span></div></button><div class="footnote">A history of doing things, not a score of who you are. New faces are welcome at every level.<br><button class="textbtn" data-action="about">About V5 & demo controls ${i('arrow')}</button></div>`}
function open(kind,args={}){closePop();if(!dialog.open)lastFocus=document.activeElement;stack.push({kind,args});drawDialog()}
function replace(kind,args={}){closePop();if(stack.length)stack[stack.length-1]={kind,args};else stack.push({kind,args});drawDialog()}
function back(){closePop();stack.pop();if(stack.length)drawDialog();else closeAll()}
function closeAll(){closePop();stack=[];if(dialog.open)dialog.close();if(lastFocus?.isConnected)lastFocus.focus()}
function shell(titleText,body,foot='',eyebrow='A LITTLE MORE POSSIBILITY'){dialog.innerHTML=`<div class="dialog-body"><div class="dialog-head">${stack.length>1?`<button class="iconbtn backbtn" data-action="back" aria-label="Back">${i('back')}</button>`:''}<div class="grow"><div class="eyebrow">${eyebrow}</div><h2 id="dialog-title">${titleText}</h2></div><button class="iconbtn" data-action="close" aria-label="Close dialog">${i('close')}</button></div>${body}</div>${foot?`<div class="dialog-foot">${foot}</div>`:''}`;if(!dialog.open)dialog.showModal();dialog.scrollTop=0}
function drawDialog(){if(!stack.length)return;const x=stack[stack.length-1];({detail:detailDialog,inspect:inspectDialog,reward:rewardDialog,create:createDialog,filters:filtersDialog,queue:queueDialog,wardrobe:wardrobeDialog,report:reportDialog,unlock:unlockDialog,memory:memoryDialog,about:aboutDialog,safety:safetyDialog,plan:planDialog,quick:quickDialog,share:shareDialog}[x.kind])(x.args)}
function showPicker(trigger,titleText,options,selected,apply,searchable=false){closePop();if(dialog.open)dialog.append(picker);else document.body.append(picker);pop={trigger,title:titleText,options,selected,apply,searchable,index:-1,filtered:options};trigger?.setAttribute('aria-expanded','true');picker.innerHTML=`<div class="pop-head"><span>${titleText}</span><button class="iconbtn" data-action="close-picker" aria-label="Close choices">${i('close')}</button></div>${searchable?`<div class="pop-search">${i('search')}<input id="pop-query" role="combobox" aria-autocomplete="list" aria-controls="pop-options" aria-expanded="true" aria-label="Filter activities" placeholder="Find your activity…" autocomplete="off"></div>`:''}<div id="pop-options" class="pop-options" role="listbox" aria-label="${esc(titleText)}"></div>`;picker.classList.remove('hidden');pickerOptions('');const r=trigger?.getBoundingClientRect()||{left:20,bottom:110};const w=Math.min(400,innerWidth-24),height=Math.min(450,innerHeight*.62);picker.style.width=w+'px';picker.style.left=Math.max(12,Math.min(r.left,innerWidth-w-12))+'px';picker.style.top=Math.max(12,Math.min(r.bottom+7,innerHeight-height-16))+'px';if(searchable)$('#pop-query').focus();else picker.querySelector('.option')?.focus()}
function pickerOptions(q){if(!pop)return;pop.filtered=pop.options.filter(o=>(o.label+' '+(o.sub||'')+' '+(o.alias||'')).toLowerCase().includes(q.toLowerCase()));pop.index=-1;$('#pop-options').innerHTML=pop.filtered.length?pop.filtered.map((o,k)=>`<button class="option ${String(o.value)===String(pop.selected)?'selected':''}" id="option-${k}" role="option" aria-selected="${String(o.value)===String(pop.selected)}" data-pick="${k}" tabindex="-1">${i(o.icon||'now')}<span class="grow"><strong style="font-weight:550">${esc(o.label)}</strong>${o.sub?'<p>'+esc(o.sub)+'</p>':''}</span>${String(o.value)===String(pop.selected)?i('check','checkico'):''}</button>`).join(''):'<p class="small muted" style="padding:15px">No supported activity matches. No substitutions were made.</p>'}
function closePop(){if(pop){pop.trigger?.setAttribute('aria-expanded','false');const t=pop.trigger;pop=null;picker.classList.add('hidden');document.body.append(picker);if(t?.isConnected)t.focus()}else picker.classList.add('hidden')}
function choose(k){if(!pop?.filtered[k])return;const p=pop,val=p.filtered[k].value;closePop();p.apply(val)}
function activityPicker(trigger,creation=false){const opts=C.catalog.map(a=>({value:a.id,label:a.name,sub:a.family+' · '+a.formats[0].name,icon:a.icon,alias:a.id}));if(!creation)opts.unshift({value:'',label:'All activities',sub:'Show every matching group nearby',icon:'now'});showPicker(trigger,creation?'Choose the activity':'What sounds good?',opts,creation?draft.a:filters.activity,val=>{if(creation){draft.a=val;draft.format=0;draft.cap=recommendCap(C.A(val),0);draft.venue=C.venues.find(v=>v.kind===C.A(val).kind).id;draft.friends=0;draft.note=C.A(val).note;drawDialog()}else{filters.activity=val;filters.family='';all=true;render()}},true)}
function recommendCap(a,format){const f=a.formats[format];return f.min===f.max?f.max:Math.min(f.max,Math.max(f.min,{cleanup:12,watch:8,photo:6,jam:5,run:6}[a.id]||4))}
function initDraft(a,friends=false){a=C.A(a)||C.A('spades');draft={a:a.id,format:0,venue:C.venues.find(v=>v.kind===a.kind).id,cap:recommendCap(a,0),friends:friends?Math.min(2,recommendCap(a,0)-2):0,mode:'open',pace:'Casual',note:a.note}}
function createDialog(){const a=C.A(draft.a),f=a.formats[draft.format],v=C.V(draft.venue);shell('Start the thing you came for.',`<p class="small muted">Pick the activity. We’ll handle the group shape.</p><div class="stack gap"><button class="select-field" data-action="draft-activity" aria-haspopup="dialog" aria-expanded="false">${i(a.icon)}<span><small>ACTIVITY</small><strong>${esc(a.name)}</strong></span>${i('down')}</button>${a.formats.length>1?`<button class="select-field" data-action="draft-format" aria-haspopup="dialog" aria-expanded="false">${i('people')}<span><small>FORMAT</small><strong>${esc(f.name)} · ${f.min===f.max?f.max+' players':f.min+'–'+f.max+' people'}</strong></span>${i('down')}</button>`:''}<button class="select-field" data-action="draft-venue" aria-haspopup="dialog" aria-expanded="false">${i('pin')}<span><small>SUGGESTED PUBLIC PLACE · CHANGE ANYTIME BEFORE PUBLISHING</small><strong>${esc(v.name)}</strong></span>${i('down')}</button></div><div class="auto-note gap">${i('spark')}<div><strong>No time to pick. We’ll start as it fills.</strong><p>Meet when ${f.min} are going. Open for the next 20 minutes.</p></div></div><div class="setting"><div><strong>${f.min===f.max?f.max+' players, exactly':'Your group size'}</strong><p>${f.min===f.max?'Set by the format, not an arbitrary app limit.':f.min+' needed to start · up to '+f.max+' allowed.'}</p></div>${f.min!==f.max?`<div class="stepper"><button data-action="draft-cap" data-dir="-1" ${draft.cap<=f.min?'disabled':''} aria-label="Reduce capacity">−</button><b>${draft.cap}</b><button data-action="draft-cap" data-dir="1" ${draft.cap>=f.max?'disabled':''} aria-label="Increase capacity">+</button></div>`:`<span class="tag blue">${draft.cap} total</span>`}</div><details class="gap-sm"><summary class="textbtn">Already with friends? Other options ${i('down')}</summary><div class="setting"><div><strong>Friends already coming with you</strong><p>Host-reported companions, not verified accounts.</p></div><div class="stepper"><button data-action="draft-friends" data-dir="-1" ${draft.friends===0?'disabled':''} aria-label="Fewer friends">−</button><b>${draft.friends}</b><button data-action="draft-friends" data-dir="1" ${draft.friends>=draft.cap-2?'disabled':''} aria-label="More friends">+</button></div></div><label class="label gap-sm">How people join</label><div class="seg"><button class="${draft.mode==='open'?'on':''}" data-action="draft-mode" data-id="open">Open to join</button><button class="${draft.mode==='request'?'on':''}" data-action="draft-mode" data-id="request">Ask me first</button></div><label class="label gap">One useful detail</label><input id="draft-note" class="input" value="${esc(draft.note)}" maxlength="120" aria-label="A useful detail for the group"></details><div class="notice gap"><strong>${draft.friends+1} coming · ${draft.cap-draft.friends-1} open spots</strong><br>${a.paid?'Pay your own; venue costs may apply':'Free sample activity'} · about ${a.minutes} minutes together.<br>Venue space, equipment, and access are host-reported, not reservations.</div>`,b('Open '+(draft.cap-draft.friends-1)+' spots '+i('arrow'),'publish','','primary full')+'<p>Publish a local demo group. No real people are notified.</p>','JUST ADD PEOPLE')}
function detailDialog({id}){const g=C.G(s,id);if(!g){shell('This group is gone.','<p class="muted">Return to the finder for current sample groups.</p>',b('Back to groups','close','','full'));return}const a=C.A(g.a),v=C.V(g.venue),blocked=!C.enabled(s,g)||!C.reachable(s,g);shell('There’s room for you.',`<div class="group-cover">${glyph(a)}<div><span class="eyebrow">${esc(C.F(g).name)}</span><h2>${esc(a.name)}</h2><p>${g.cap-C.members(g)} open spots · ${a.paid?'pay your own':'free'}</p></div></div><div class="fact">${i('pin')}<div><strong>${esc(v.name)}</strong><p>${v.eta}-minute sample walk · ${esc(v.note)}</p></div></div><div class="fact">${i('clock')}<div><strong>${g.meetAt?'Group meeting time is set':'Starts when '+C.F(g).min+' are going'}</strong><p>${a.minutes} minutes together · join window closes in ${Math.max(0,Math.ceil((g.closes-C.now(s))/60000))} min</p></div></div><p class="small muted gap-sm">${esc(g.note)}</p><div class="collectionbar"><h3>The people make it.</h3><span>Tap anyone to inspect</span></div>${roster(g)}${g.guests?'<p class="roster-note">*Includes '+g.guests+' host-reported companions. They do not supply independent account evidence.</p>':''}<div class="notice gap"><strong>${g.mode==='request'?'A request is not a confirmed place.':'One “I’m in” is enough.'}</strong><br>${g.mode==='request'?'The host can inspect and invite you. You still accept the actual plan before going.':'Joining confirms this activity and public place. A clear meeting time follows when the group is ready.'} ${g.cap===2?'This is a two-person meeting with someone you may not know. ':''}You can leave any time.</div>${blocked?'<p class="error">No longer reachable or available. No spot can be claimed.</p>':''}`,`<button class="btn primary full" data-action="${g.mode==='request'?'request':'join'}" data-id="${id}" ${blocked||s.active||s.pending?'disabled':''}>${s.active||s.pending?'You already have a group or request':g.mode==='request'?'Ask to join '+i('arrow'):'I’m in · '+v.eta+'-min walk '+i('arrow')}</button><p>Fictional venue and people. No real booking or message.</p>`,'THE PLAN, BEFORE THE YES')}
function roster(g){const max=g.members.length>12?12:g.members.length;return `<div class="people-grid">${g.members.slice(0,max).map(id=>`<button class="person-tile" data-action="inspect" data-id="${id}" data-group="${g.id}">${char(id)}<strong>${id==='me'?'You':esc(person(id).name)}</strong><small>${g.proof.includes(id)?'Confirmed*':g.here.includes(id)?'Self check-in':g.going.includes(id)?'Going': 'Joined'}${g.host===id?' · host':''}</small></button>`).join('')}${g.members.length>max?`<div class="person-tile empty-seat"><span class="empty-circle">+${g.members.length-max}</span><small>Registered</small></div>`:''}${g.guests?`<div class="person-tile empty-seat"><span class="empty-circle">+${g.guests}</span><strong>With host</strong><small>Reported</small></div>`:''}${C.members(g)<g.cap?`<div class="person-tile empty-seat"><span class="empty-circle">+</span><strong>${g.cap-C.members(g)} open</strong><small>${Math.max(0,C.F(g).min-C.members(g))||'No more'} needed</small></div>`:''}</div>`}
function ownPersonState(id){if(id==='me')return s;const p=person(id);return{record:p.record,types:Array.from({length:p.record.types||0},(_,i)=>'seed'+i),earned:C.rewards.filter(r=>(r.metric==='types'?p.record.types:p.record[r.metric]||0)>=r.goal).map(r=>r.id)}}
function personAwards(id){return ownPersonState(id).earned}
function inspectDialog({id,groupId,tab='Card'}){const p=person(id),g=C.G(s,groupId||s.active),a=g?C.A(g.a):null,rstate=ownPersonState(id),related=a?(p.record[a.id]||0):0,awards=personAwards(id),pins=id==='me'?s.showcase:awards.slice(-3),hostCanInvite=g?.host==='me'&&g.requests.includes(id);shell(id==='me'?'Your player card.':`${esc(p.name)}’s player card.`,`<div class="profile-stage"><div><span class="eyebrow">${id==='me'?'A LITTLE MORE YOU':'GOOD TO KNOW'}</span><h2>${esc(p.name)}</h2><p>${esc(p.bio)}</p><span class="tag">${awards.includes('cards')?'Wild card':awards.includes('curious')?'Curious by nature':'New here · welcome'}</span></div><div class="character">${char(id)}</div></div>${a?`<div class="context-record">${i(a.icon)}<div><strong>${related} ${esc(a.name.toLowerCase())} rounds</strong><p>Relevant sample history · ${esc(p.pace)} is self-described</p></div></div>`:''}<div class="statrow"><div><strong>${p.record.rounds||0}</strong><small>sample rounds</small></div><div><strong>${p.record.repeat||0}</strong><small>repeat dates*</small></div><div><strong>${C.ap(rstate)}</strong><small>achievement points</small></div></div><div class="profile-tabs">${['Card','Collection','Rounds'].map(t=>`<button class="${tab===t?'on':''}" data-action="inspect-tab" data-id="${id}" data-tab="${t}" data-group="${g?.id||''}">${t}</button>`).join('')}</div>${tab==='Collection'?`<div class="collectionbar"><h3>${esc(p.name)}’s collection</h3><span>${awards.length} earned</span></div><div class="collection-grid">${awards.map(r=>rewardCard(C.R(r),id)).join('')}</div>`:tab==='Rounds'?`<div class="history-line">${glyph(C.A('spades'))}<div><h3>${p.record.spades||0} card rounds</h3><p>Seeded sample history · no exact venues or timestamps</p></div></div><div class="history-line">${glyph(C.A('pickleball'))}<div><h3>${p.record.pickleball||0} pickleball rounds</h3><p>Participation, not an ability rating</p></div></div>`:`<div class="collectionbar"><h3>Things worth keeping.</h3><span>Tap to inspect</span></div><div class="pin-row">${pins.map(r=>`<button class="pin-btn" data-action="reward" data-id="${r}" data-owner="${id}">${badge(C.R(r))}<strong>${C.R(r).name}</strong></button>`).join('')||'<p class="small muted">New here. No achievements are needed to join.</p>'}</div><p class="profile-about">${esc(p.bio)}<br>*History is seeded or based on simulated participant reports. It is not identity verification, skill certification, a reliability percentage, or a safety guarantee.</p>`}${id!=='me'?'<button class="textbtn danger gap-sm" data-action="safety" data-id="'+id+'">Block or get help '+i('shield')+'</button>':''}`,hostCanInvite?b('Invite '+esc(p.name)+' '+i('arrow'),'invite',id,'primary full')+b('Decline request','decline',id,'quiet full')+'<p>An invitation does not occupy a seat until they accept.</p>':id==='me'?b('Customize your character','wardrobe','','primary full'):b(g?'Back to '+C.A(g.a).name:'Back','back','','full'),'PLAYER CARD')}
function rewardCard(r,owner='me'){const state=ownPersonState(owner),yes=state.earned.includes(r.id),v=Math.min(r.goal,C.metric(state,r));return `<button class="reward-card ${yes?'':'locked'}" data-action="reward" data-id="${r.id}" data-owner="${owner}"><div class="state"><span>${yes?'Collected':'In the making'}</span>${i(yes?'check':'lock')}</div>${badge(r)}<h3>${r.name}</h3><p>${r.family} · ${r.ap} AP</p><div class="meter"><span style="width:${v/r.goal*100}%"></span></div><div class="row between small muted" style="font-size:9px;margin-top:6px"><span>${yes?'Earned':v+' / '+r.goal}</span><span>${yes?'See the story':'See how'}</span></div></button>`}
function rewardDialog({id,owner='me'}){const r=C.R(id),state=ownPersonState(owner),yes=state.earned.includes(id);shell(owner==='me'?'A small story. Yours to keep.':`From ${esc(person(owner).name)}’s collection.`,`<div class="reward-detail">${badge(r)}<h2>${r.name}</h2><p>${r.story}</p><span class="tag gold">${r.ap} AP · ${yes?'earned':Math.min(r.goal,C.metric(state,r))+' / '+r.goal}</span></div><div class="reward-proof"><strong>How it unlocks</strong><br>${r.rule}<br><br><strong>Evidence</strong><br>${yes?'Seeded history or explicitly simulated reciprocal reports.':'Requires completed activity supported by participant reports. Joining or self check-in is insufficient.'} No AP threshold for ordinary groups. No skill, identity, or safety claim.</div>`,owner!=='me'?b('Back to player card','back','','full'):yes?b(s.wear===id?'Wearing this':'Wear the story '+i('spark'),'wear',id,'primary full')+b(s.showcase.includes(id)?'Unpin from player card':'Pin to player card','pin',id,'quiet full'):b('Find a matching group '+i('arrow'),'find-reward',id,'primary full'),'THE COLLECTION, NOT A SCOREBOARD')}
function youView(){return `<section class="you-page">${title('A life with a little more to it.','Keep the experiences. Make them yours.')}<div class="profile-stage"><div><span class="eyebrow">JAMIE’S PLAYER CARD</span><h2>${s.wear==='none'?'Open to something.':C.R(s.wear).name}</h2><p>${s.record.rounds} sample rounds · ${s.earned.length} collected</p><span class="tag blue">${C.ap(s)} AP · experiences, not a rank</span>${b('Make it yours '+i('pen'),'wardrobe','','gap')}</div><div class="character">${char('me')}</div></div><div class="pin-row gap">${s.showcase.map(id=>`<button class="pin-btn" data-action="reward" data-id="${id}">${badge(C.R(id))}<strong>${C.R(id).name}</strong></button>`).join('')}</div><div class="profile-tabs">${['Collection','Your rounds'].map(t=>`<button class="${youTab===t?'on':''}" data-action="you-tab" data-id="${t}">${t}</button>`).join('')}</div>${youTab==='Your rounds'?historyView():`<div class="collectionbar"><h3>Little stories, real personality.</h3><span>${s.earned.length}/${C.rewards.length} collected</span></div><div class="tabs">${['All','Earned','Your thing','Together','Side quests'].map(t=>`<button class="chip ${collection===t?'on':''}" data-action="collection" data-id="${t}">${t}</button>`).join('')}</div><div class="collection-grid">${C.rewards.filter(r=>collection==='All'||(collection==='Earned'?s.earned.includes(r.id):r.family===collection)).map(r=>rewardCard(r)).join('')}</div>`}<div class="endline">No streaks to lose. No level needed to belong.<br>Every account, object, and completion here is a local demonstration.</div></section>`}
function wardrobeDialog(){shell('A little more you.',`<div class="wardrobe">${char('me')}</div><label class="label">Your color · all free</label><div class="swatches">${colors.map((c,k)=>`<button class="swatch ${s.tone===k?'on':''}" style="--sw:${c[0]}" data-action="tone" data-value="${k}" aria-label="${['Apricot','Blue','Sage','Gold','Lilac'][k]} character" aria-pressed="${s.tone===k}"></button>`).join('')}</div><label class="label gap">Start with your style</label><div class="seg">${['none','cap','beanie'].map(h=>`<button class="${s.hat===h?'on':''}" data-action="hat" data-id="${h}">${h==='none'?'Keep it simple':h==='cap'?'Everyday cap':'Soft beanie'}</button>`).join('')}</div><label class="label gap">Carry something you earned</label><div class="wear-options"><button class="${s.wear==='none'?'on':''}" data-action="wardrobe-wear" data-id="none">Just me</button>${s.earned.map(id=>`<button class="${s.wear===id?'on':''}" data-action="wardrobe-wear" data-id="${id}">${C.R(id).name}</button>`).join('')}</div><p class="small muted gap">Appearance is yours from day one. The things you do can add a little story, never a matchmaking advantage.</p>`,b('That’s me '+i('check'),'back','','primary full'),'PERSONALITY IS NOT A PAYWALL')}
function groupView(){if(!s.active&&s.pending){const g=C.G(s,s.pending.id),invited=s.pending.phase==='invited',openNow=C.enabled(s,g)&&C.reachable(s,g);return `${title(invited?'A spot has your name on it.':'Your request is in.','No seat is claimed until both sides say yes.')}<div class="party-panel"><div class="group-cover">${glyph(C.A(g.a))}<div><h2>${C.A(g.a).name}</h2><p>${C.V(g.venue).name} · ${g.cap-C.members(g)} spots currently open</p></div></div><p class="small muted gap">${invited?'The sample host invited you. Review the actual plan before accepting.':'Waiting for a host response. This is a fictional request, not a real notification.'}</p>${invited?`<button class="btn primary full gap" data-action="accept" ${!openNow?'disabled':''}>${openNow?'Accept the spot':'The window has closed'}</button>`:''}<button class="textbtn danger gap-sm" data-action="cancelRequest">Withdraw request</button>${!invited?lab(b('Simulate the host’s invitation','simHostAccept','','full')):''}</div>`}
 const g=C.G(s);if(!g)return `${title('This is where a group happens.','A clear plan. Good people. One place to talk.')}<div class="empty">${i('people')}<h3>Find your next good thing.</h3><p>Join something nearby, or open the missing places in your own group.</p>${b('Find a group '+i('arrow'),'nav','find','primary')}</div>`;
 const a=C.A(g.a),v=C.V(g.venue);let h='',text='',next='';if(g.phase==='forming'){h='A little room for more.';text=`${g.going.length+(g.guestGoing?g.guests:0)} going. ${Math.max(0,C.F(g).min-g.going.length-(g.guestGoing?g.guests:0))} more needed for ${C.F(g).name.toLowerCase()}. No need to set out yet.`;next=b('Share the open spots '+i('share'),'share','','full')}
 else if(g.phase==='ready'){h='You’re going. The group is on.';text=`The group meets in about ${Math.max(0,Math.ceil((g.meetAt-C.now(s))/60000))} min. Your sample walk is ${v.eta} min. ${g.meetAt-C.now(s)<v.eta*60000?'Join them as you arrive; don’t rush.':'One yes was enough.'}`;next=b('The meeting point '+i('pin'),'plan','','primary full')}
 else if(g.phase==='meeting'){h=g.here.includes('me')?'Enjoy the company.':'Find your people.';text=g.here.includes('me')?'Your check-in is a claim, not proof. Finish the experience before reporting it.':'The meeting window is open. You can leave whenever you need to.';next=b(g.here.includes('me')?'After the round '+i('arrow'):'I’m here '+i('check'),g.here.includes('me')?'report':'here','','primary full')}
 else if(g.phase==='pending'){h='Your part is done.';text='You reported who you met. Waiting on independent confirmation. Points have not changed.';next=b('Review my report','report','','full')}
 else if(g.phase==='complete'){h='A good thing, kept.';const rec=s.history.find(x=>x.id===g.id);text=rec?.format?'The format is corroborated in this fictional walkthrough.':'Participation is corroborated; the full activity format was not.';next=b('See what you kept '+i('spark'),'completion','','primary full')}
 else{h='This one didn’t come together.';text='The window ended or the group was canceled. No invented attendance or public penalty.';next=b('Find another group','leave','','full')}
 let demo='';if(g.phase==='forming')demo=b('Simulate enough people saying yes','simFill','','full');if(g.phase==='ready')demo=b('Jump to the meeting','simMeet','','full');if(g.phase==='meeting'&&g.here.includes('me'))demo=b('Finish sample activity & report','simFinish','','full');if(g.phase==='pending')demo=b('Simulate reciprocal confirmations','simProof','','full');if(g.host==='me'&&C.enabled(s,g))demo+=b('Add a sample join request','simCandidate','','full');
 return `<div class="party-head">${glyph(a)}<div><h1>${a.name}</h1><p>${C.F(g).name} · ${g.cap} places · ${a.minutes} min together</p></div></div>${hostRequests(g)}<div class="party-panel"><div class="phase-row"><span class="eyebrow">${g.phase==='ready'?'READY TO MEET':g.phase==='complete'?'SAVED EXPERIENCE':g.phase.toUpperCase()}</span><span class="tag blue">${C.members(g)}/${g.cap} going${g.guests?'*':''}</span></div><h2>${h}</h2><p class="small muted">${text}</p>${roster(g)}<div class="plan-tile">${i('pin')}<div><strong>${v.name}</strong><p>${esc(v.note)}</p></div><button class="iconbtn" data-action="plan" aria-label="See meeting point">${i('arrow')}</button></div><div class="gap-sm">${next}</div><div class="progress-steps">${[1,2,3,4].map(k=>`<span class="${k<=({forming:1,ready:2,meeting:3,pending:3,complete:4}[g.phase]||0)?'on':''}"></span>`).join('')}</div></div><div class="chat-title"><h3>Say a quick hello.</h3><small>Fictional group · local only</small></div><div id="messages" class="messages" aria-live="polite"></div>${['forming','ready','meeting','pending'].includes(g.phase)?`<div class="reply-row"><button data-action="quick" data-id="Hey everyone! See you there.">Say hello</button><button data-action="quick" data-id="First time trying this. Thanks for making room!">I’m new to this</button><button data-action="plan">Where exactly?</button></div><form id="chat-form" class="composer"><button class="iconbtn" type="button" data-action="sticker" aria-label="Send your character waving">${i('wave')}</button><input id="chat-input" aria-label="Message your group" placeholder="Message your group…" maxlength="400" autocomplete="off"><button class="send" type="submit" aria-label="Send local demo message" disabled>${i('arrow')}</button></form>`:''}${demo?lab(demo):''}<div class="party-footer"><button class="textbtn ${g.phase==='complete'?'':'danger'}" data-action="leave">${g.phase==='complete'?'Close completed group':'Leave this group'}</button><button class="textbtn" data-action="safety">Help & safety ${i('shield')}</button></div>`}
function lab(buttons){return `<details class="demo-lab" open><summary>Walk through the full experience · demo controls</summary><p>These explicit controls simulate time or other people. Consumer actions never secretly fabricate participants or confirmation.</p>${buttons}</details>`}
function hostRequests(g){if(g.host!=='me'||!g.requests.length&&!g.invited.length)return '';return `<div class="request-card"><h3>${g.requests.length} ${g.requests.length===1?'person wants':'people want'} in</h3><p class="small muted">Inspect their activity history. An invitation is not attendance.</p>${g.requests.map(id=>`<div class="request-line">${char(id)}<div class="grow"><strong>${person(id).name}</strong><p>${person(id).record[g.a]||0} related sample rounds · ${person(id).pace}</p></div>${b('Inspect '+i('arrow'),'inspect-request',id)}</div>`).join('')}${g.invited.map(id=>`<div class="request-line">${char(id)}<div class="grow"><strong>${person(id).name} · invited</strong><p>Waiting for their own yes. No seat occupied yet.</p></div>${b('Demo: accept','simRSVP',id)}</div>`).join('')}</div>`}
function drawMessages(){const g=C.G(s);if(!g||!$('#messages'))return;$('#messages').innerHTML=`<div class="message">${face(g.host)}<div><p class="message-name">${person(g.host).name} · sample message</p><div class="bubble">${esc(g.note)}</div></div></div>${g.chat.map(m=>`<div class="message mine">${face('me')}<div><p class="message-name">You · on this device</p><div class="bubble ${m.kind==='wave'?'sticker':''}">${m.kind==='wave'?char('me'):esc(m.text)}</div></div></div>`).join('')}`;$('#messages').scrollTop=$('#messages').scrollHeight}
function planDialog(){const g=C.G(s);if(!g)return;const a=C.A(g.a),v=C.V(g.venue);shell('The same plan for everyone.',`<div class="group-cover">${glyph(a)}<div><h2>${a.name}</h2><p>${C.F(g).name}</p></div></div><div class="fact">${i('pin')}<div><strong>${v.name}</strong><p>${v.note}</p></div></div><div class="fact">${i('clock')}<div><strong>${g.meetAt?'Meeting time set after the group confirmed':'We’ll set out when enough people confirm'}</strong><p>${a.minutes} minutes together · invitation does not renew itself</p></div></div><div class="notice gap">All places and travel times are fictional fixtures. No map, reservation, equipment check, or real navigation is connected. Access shown as step-free is host-reported, not verified.</div>`,b('Back to the group','back','','primary full'),'MEET PUBLICLY. LEAVE FREELY.')}
function reportDialog(){const g=C.G(s);if(!g||!['meeting','pending'].includes(g.phase)||!g.here.includes('me')||C.now(s)<g.meetAt+C.A(g.a).minutes*60000){shell('Enjoy the round first.','<p class="small muted">You must check in and finish the sample activity before reporting. Use the labeled demo time control, not a fake completion button.</p>',b('Back to the group','back','','primary full'));return}shell('Who did you actually meet?',`<p class="small muted">Your first report starts unchecked. Select people, not a rating.</p><div class="gap">${g.members.filter(id=>id!=='me').map(id=>`<label class="checkrow"><input name="met" type="checkbox" value="${id}" ${g.report?.includes(id)?'checked':''}>${face(id)}<span>${esc(person(id).name)}<small>Registered sample participant</small></span></label>`).join('')}</div>${g.guests?'<p class="small muted gap">Host-reported companions do not count as independent witnesses.</p>':''}<div class="notice gap">Your report alone earns nothing. Missing evidence is not proof of a lie. Exact-format achievements need the format itself corroborated.</div>`,b('Save my report '+i('arrow'),'save-report','','primary full'),'AFTER THE EXPERIENCE')}
function completion(){if(!C.G(s)||C.G(s).phase!=='complete')return;if(lastAwards.length&&s.celebrate)open('unlock');else open('memory',{id:s.active})}
function unlockDialog(){const r=C.R(lastAwards[0]);if(!r){replace('memory',{id:s.active});return}shell('That became part of your story.',`<div class="unlock"><div class="eyebrow">A NEW THING TO KEEP</div><div class="unlock-stage">${avatar(s.tone,s.hat,r.wear)}</div><span class="tag gold">+${lastAwards.reduce((n,id)=>n+C.R(id).ap,0)} AP · ${lastAwards.length} ${lastAwards.length===1?'unlock':'unlocks'}</span><h2>${r.name}</h2><p>${r.story}</p>${lastAwards.length>1?'<div class="notice">Also unlocked: '+lastAwards.slice(1).map(id=>C.R(id).name).join(', ')+'.</div>':''}</div>`,b('Put it on '+i('spark'),'wear-new',r.id,'primary full')+b('Keep the memory','memory',s.active,'quiet full')+'<p>Unlocked only after explicitly simulated participant confirmations.</p>','THE GOOD PART LASTS')}
function memoryDialog({id}){const h=s.history.find(x=>x.id===id)||s.history[0];if(!h){shell('No completed round yet.','<p class="small muted">Complete a fictional group first.</p>',b('Back','back','','full'));return}shell('We made it a round.',`<div class="memory"><div class="eyebrow">ROUND / A FICTIONAL KEEPSAKE</div><div class="characters">${['me','p0','p1','p2'].slice(0,Math.min(h.people,4)).map(id=>char(id)).join('')}</div><h3>Good company.<br>One small yes.</h3><p>${C.A(h.a).name} · ${h.people} simulated participants</p></div><p class="small muted gap">Private to this browser. Export uses anonymous characters with no participant names, exact time, or venue. It remains visibly labeled as fictional.</p>`,b('Save the keepsake '+i('share'),'export',h.id,'primary full')+b('See your collection','view-collection','','quiet full'),'NOT EVERYTHING NEEDS AN AUDIENCE')}
function filtersDialog(){const f=filterDraft;shell('Keep the good fits.',`<p class="small muted">Your filters stay yours. We never widen them quietly.</p><div class="gap"><label class="label">Time for the whole thing</label><div class="seg">${[0,30,60,90].map(n=>`<button class="${f.duration===n?'on':''}" data-action="filter-duration" data-value="${n}">${n?n+' min':'Any'}</button>`).join('')}</div><p class="small muted gap-sm">Includes the estimated trip and the activity, not only the start.</p></div><div class="setting"><div><strong>Free activities only</strong><p>No expected purchase in the sample plan.</p></div><button class="toggle ${f.free?'on':''}" data-action="filter-free" role="switch" aria-checked="${f.free}" aria-label="Free activities only"></button></div><div class="setting"><div><strong>Step-free meeting point</strong><p>Host-reported access, not independently verified.</p></div><button class="toggle ${f.access?'on':''}" data-action="filter-access" role="switch" aria-checked="${f.access}" aria-label="Step-free meeting point"></button></div><div class="gap"><label class="label">Self-described pace</label><div class="seg">${['','Casual','Newcomer'].map(p=>`<button class="${f.pace===p?'on':''}" data-action="filter-pace" data-id="${p}">${p||'Any pace'}</button>`).join('')}</div></div>`,b('Show matching groups '+i('arrow'),'apply-filters','','primary full'),'LESS NOISE. YOUR KIND OF THING.')}
function queueDialog(){shell('Open to a few good things?',`<p class="small muted">Pick up to three. Interest lasts twenty minutes and stays private. It never commits you.</p><div class="wear-options gap">${['coffee','spades','pickleball','walk','ideas','read','basketball','jam'].map(id=>`<button class="${queueDraft.includes(id)?'on':''}" data-action="queue-choice" data-id="${id}" aria-pressed="${queueDraft.includes(id)}">${C.A(id).name}</button>`).join('')}</div><div class="notice gap">This stores a local demo interest. No live matchmaking, notifications, or nearby-person map is connected.</div>`,b('Keep these open','save-queue','','primary full'),'A SOFT YES, NOT A COMMITMENT')}
function quickDialog(){const g=C.list(s,filters)[0];shell(g?'One less decision.':'No fitting group right now.',g?`<div class="group-cover">${glyph(C.A(g.a))}<div><h2>${C.A(g.a).name}</h2><p>${g.cap-C.members(g)} open spots · ${C.V(g.venue).eta}-min walk</p></div></div><p class="small muted gap">This fits your activity and travel settings. It is already close to a viable group. Your points, appearance, and popularity are not used.</p><div class="notice gap">A deterministic sample suggestion, not connected AI. You still inspect the plan and choose.</div>`:'<p class="small muted">Your actual filters found nothing reachable. There is no fake fallback group.</p>',g?b('See the group '+i('arrow'),'detail',g.id,'primary full'):b('Keep my options open','queue','','primary full'),'FIND ME A FIT')}
function peopleView(){return `${title('Good people. Again.','The people you kept, not a list of followers.')}<div class="notice">Sample mutual connections. Availability is private and off by default. No live position is shown.</div>${[['p0','spades','Three good tables together.'],['p3','pickleball','Two sample court days.'],['p2','walk','The easy route, with good company.']].filter(([id])=>!s.blocked.includes(id)).map(([id,a,text])=>`<div class="friend-card"><div class="row">${char(id)}<div class="grow"><h3>${person(id).name}</h3><p>${text}</p></div><button class="iconbtn" data-action="inspect" data-id="${id}" aria-label="Inspect ${person(id).name}">${i('arrow')}</button></div>${b('Start '+C.A(a).name+' '+i('plus'),'crew-start',a,'full')}</div>`).join('')}<div class="collectionbar"><h3>A few good things.</h3><span>Sample opt-in highlights</span></div><div class="moment">${badge(C.R('rally'))}<div><p><b>Alex</b> found some rally energy.</p><small>Participation, not wins. Fictional history.</small></div></div><div class="moment">${badge(C.R('cards'))}<div><p><b>Maya</b> played a wild card.</p><small>A story on a player card, not a public score.</small></div></div><div class="endline">That’s the whole feed. Go make something worth keeping.</div>`}
function historyView(){return s.history.length?s.history.map(h=>`<div class="history-line">${glyph(C.A(h.a))}<div class="grow"><h3>${C.A(h.a).name}</h3><p>${h.people} simulated confirmations · ${h.format?'format corroborated':'participation only'}</p></div><button class="iconbtn" data-action="memory" data-id="${h.id}" aria-label="View keepsake">${i('arrow')}</button></div>`).join(''):'<div class="empty gap">'+i('ticket')+'<h3>A little room for memories.</h3><p>Your starting history is seeded. Finish a sample group to add a new keepsake.</p>'+b('Find a group','nav','find','primary')+'</div>'}
function aboutDialog(){shell('The real V5. A fictional world.',`<div class="notice"><strong>Release 5.0.0 · Springboard</strong><br>A complete local prototype. Not a multiuser service. Round is a working name.</div><p class="small muted gap">50 curated activity templates, activity-specific formats, modern choice menus, one-step commitment, member inspection, host invitations, local chat, earned collectibles, and explicit demo evidence.</p><p class="small muted gap">No real accounts, GPS, venue booking, remote messages, AI model, payments, push delivery, or staffed safety response. ${storage?'Demo state is saved in this browser.':'Storage is unavailable; this session is in-memory only.'}</p><div class="setting"><div><strong>Celebrate new rewards</strong><p>No sound, streak penalties, or randomized loot.</p></div><button class="toggle ${s.celebrate?'on':''}" role="switch" aria-label="Reward celebrations" aria-checked="${s.celebrate}" data-action="celebrate"></button></div><div class="stack gap">${b('Share the prototype '+i('share'),'share','','full')}${b('Advance demo time 21 minutes','advance','','full')}${b('Reset V5 demo data','reset','','full')}</div><p class="small muted gap">Adults-only concept. Public places. Capacity, reports, and invitations need authenticated server enforcement before any real-user pilot.</p>`,'','CLEAR ABOUT WHAT IS REAL')}
function safetyDialog({id}){shell('You can always leave.',`<div class="notice"><strong>No operational response team is connected.</strong><br>This demo cannot handle a real emergency or receive a safety report. Contact local emergency help when appropriate.</div><p class="small muted gap">Achievements are evidence of activity, not proof that someone is safe, honest, or skilled. Missing a confirmation does not prove a lie.</p>${id&&id!=='me'?`<div class="request-card"><h3>Block ${esc(person(id).name)} locally</h3><p class="small muted gap-sm">Leaves any shared active group first, then hides their sample groups. No public penalty or accusation.</p>${b('Leave & block locally','block',id,'full gap-sm')}</div>`:''}<p class="small muted gap">Production release requires staffed reporting, evidence access controls, block enforcement, appeals, venue operations, and clear retention rules.</p>`,b('Back','back','','full'),'HELP WITHOUT FALSE ASSURANCE')}
function exportMemory(id){const h=s.history.find(x=>x.id===id);if(!h)return;const faces=[0,1,2,3].slice(0,Math.min(4,h.people)).map((c,j)=>`<g transform="translate(${90+j*103} 143) scale(.67)">${avatar(c)}</g>`).join('');const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="640" height="440" viewBox="0 0 640 440"><rect width="640" height="440" rx="25" fill="#f5f0df"/><circle cx="320" cy="235" r="150" fill="#e9e2c9"/><text x="320" y="58" text-anchor="middle" font-family="sans-serif" font-size="11" fill="#6b705e" letter-spacing="2">ROUND V5 / FICTIONAL DEMO KEEPSAKE</text>${faces}<text x="320" y="333" text-anchor="middle" font-family="sans-serif" font-size="32" fill="#253123">Good company. One small yes.</text><text x="320" y="368" text-anchor="middle" font-family="sans-serif" font-size="15" fill="#65705b">${esc(C.A(h.a).name)}</text><text x="320" y="410" text-anchor="middle" font-family="sans-serif" font-size="10" fill="#65705b">Anonymous illustrated characters. Not evidence of a real meetup.</text></svg>`;const u=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'})),a=document.createElement('a');a.href=u;a.download='round-v5-demo-keepsake.svg';a.click();setTimeout(()=>URL.revokeObjectURL(u),3000);toast('Kept. No names, venue, or exact time in the export.')}
function shareDialog(){const link='https://raw.githack.com/Vitalisrx/round-prototype/main/index.html';shell('Share a little possibility.',`<p class="small muted">This opens the public prototype, not your local messages, progress, or a real invitation.</p><input class="input gap" id="share-url" value="${link}" readonly aria-label="Prototype link"><div class="notice gap">Use the updating <strong>main</strong> link. Old commit-pinned links deliberately remain older versions. The page header should say ROUND V5.</div>`,b('Copy prototype link '+i('share'),'copy-link','','primary full'),'ONE LINK. NO PRIVATE STATE.')}
function reset(){s=C.seed();filters={activity:'',family:'',travel:15,pace:'',free:false,access:false,duration:0};all=false;lastAwards=[];save();go('find');toast('Fresh fictional groups. V5 demo state reset.')}
function onAction(e){const pick=e.target.closest('[data-pick]');if(pick){choose(+pick.dataset.pick);return}const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const ac=el.dataset.action,id=el.dataset.id,g=C.G(s);switch(ac){
 case'nav':go(id);break;case'close':closeAll();break;case'back':back();break;case'close-picker':closePop();break;
 case'choose-filter-activity':activityPicker(el);break;case'choose-travel':showPicker(el,'How close?', [5,10,15,20].map(n=>({value:n,label:'Within a '+n+'-minute walk',sub:n===15?'Default · sample travel estimates':'Uses fictional walking estimates',icon:'pin'})),filters.travel,n=>{filters.travel=+n;render()});break;
 case'family':filters.family=id;filters.activity='';all=false;render();break;case'more':all=true;drawList();break;case'clear':filters={activity:'',family:'',travel:15,pace:'',free:false,access:false,duration:0};render();break;
 case'filters':filterDraft=copy(filters);open('filters');break;case'filter-duration':filterDraft.duration=+el.dataset.value;drawDialog();break;case'filter-free':filterDraft.free=!filterDraft.free;drawDialog();break;case'filter-access':filterDraft.access=!filterDraft.access;drawDialog();break;case'filter-pace':filterDraft.pace=id;drawDialog();break;case'apply-filters':filters=copy(filterDraft);go('find');break;
 case'detail':open('detail',{id});break;case'join':if(act('join',{id})){go('group');toast('You’re in. One clear yes, one group.')}break;case'request':if(act('request',{id})){go('group');toast('Local request saved. No seat is occupied yet.')}break;case'accept':if(act('accept'))go('group');break;case'cancelRequest':if(act('cancelRequest'))go('find');break;case'simHostAccept':act('simHostAccept');break;
 case'create':initDraft(filters.activity);open('create');break;case'create-friends':initDraft('spades',true);open('create');break;case'crew-start':initDraft(id);open('create');break;
 case'draft-activity':activityPicker(el,true);break;case'draft-format':showPicker(el,'Choose the format',C.A(draft.a).formats.map((f,k)=>({value:k,label:f.name,sub:f.min===f.max?f.max+' players exactly':f.min+'–'+f.max+' people',icon:'people'})),draft.format,k=>{draft.format=+k;draft.cap=recommendCap(C.A(draft.a),+k);draft.friends=Math.min(draft.friends,draft.cap-2);drawDialog()});break;
 case'draft-venue':showPicker(el,'Suggested public places',C.venues.filter(v=>v.kind===C.A(draft.a).kind).map(v=>({value:v.id,label:v.name,sub:v.eta+'-min sample walk · not reserved',icon:'pin'})),draft.venue,k=>{draft.venue=k;drawDialog()});break;
 case'draft-cap':draft.cap=Math.max(C.A(draft.a).formats[draft.format].min,Math.min(C.A(draft.a).formats[draft.format].max,draft.cap+(+el.dataset.dir)));draft.friends=Math.min(draft.friends,draft.cap-2);drawDialog();break;case'draft-friends':draft.friends=Math.max(0,Math.min(draft.cap-2,draft.friends+(+el.dataset.dir)));drawDialog();dialog.querySelector('details').open=true;break;
 case'draft-mode':draft.mode=id;drawDialog();dialog.querySelector('details').open=true;break;case'publish':if(act('create',draft)){go('group');toast('Group created locally. The activity set the format.')}break;
 case'inspect':{const context=el.dataset.group||stack.findLast?.(x=>x.kind==='detail')?.args.id||g?.id;open('inspect',{id,groupId:context});break}case'inspect-request':open('inspect',{id,groupId:g?.id});break;case'inspect-tab':replace('inspect',{id,groupId:el.dataset.group,tab:el.dataset.tab});break;
 case'invite':if(act('invite',{id})){closeAll();render();toast('Demo invitation created. Their acceptance still matters.')}break;case'decline':if(act('decline',{id})){closeAll();render();toast('Request declined locally. No public rating.')}break;case'simRSVP':act('simRSVP',{id});break;case'simCandidate':{const candidate=['p0','p1','p3','p9'].find(id=>!g.members.includes(id)&&!g.requests.includes(id)&&!g.invited.includes(id)&&!s.blocked.includes(id));if(candidate)act('simCandidate',{id:candidate});else toast('All sample candidates already have a request or place.');break}
 case'simFill':act('simFill');break;case'simMeet':act('simMeet');break;case'here':act('here');break;case'simFinish':if(act('simFinish'))open('report');break;case'report':open('report');break;case'save-report':if(act('report',{ids:[...dialog.querySelectorAll('input[name="met"]:checked')].map(x=>x.value)})){closeAll();render()}break;case'simProof':{const r=act('simProof');if(r){lastAwards=r.earned;completion()}break}case'completion':completion();break;case'leave':if(act('leave'))go('find');break;case'plan':open('plan');break;
 case'quick':if(act('chat',{text:id},false))drawMessages();break;case'sticker':if(act('sticker',{},false))drawMessages();break;
 case'reward':open('reward',{id,owner:el.dataset.owner||'me'});break;case'wear':if(act('wear',{id})){drawDialog();toast('Wearing your story.')}break;case'wear-new':if(act('wear',{id})){go('you');toast('It’s yours. Put the experience on.')}break;case'pin':if(act('pin',{id})){drawDialog();toast('Your player-card showcase is updated.')}break;
 case'wardrobe':open('wardrobe');break;case'tone':if(act('customize',{tone:+el.dataset.value}))drawDialog();break;case'hat':if(act('customize',{hat:id}))drawDialog();break;case'wardrobe-wear':if(act('wear',{id}))drawDialog();break;
 case'find-reward':{const r=C.R(id),map={full:'spades',types:'',rounds:'',hosted:'',repeat:''};filters.activity=C.A(r.metric)?r.metric:(map[r.metric]||'');filters.family='';go('find');break}case'collection':collection=id;render();break;case'you-tab':youTab=id;render();break;case'view-collection':go('you');break;
 case'memory':open('memory',{id});break;case'export':exportMemory(id);break;
 case'queue':queueDraft=s.queue?[...s.queue.ids]:[filters.activity||'coffee'];open('queue');break;case'queue-choice':if(queueDraft.includes(id))queueDraft=queueDraft.filter(x=>x!==id);else if(queueDraft.length<3)queueDraft.push(id);else toast('Pick up to three.');drawDialog();break;case'save-queue':if(act('queue',{ids:queueDraft})){go('find');toast('Local interest saved for twenty minutes.')}break;case'stopQueue':act('stopQueue');break;case'quickmatch':open('quick');break;
 case'about':open('about');break;case'celebrate':if(act('celebrate',{value:!s.celebrate}))drawDialog();break;case'advance':if(act('advance',{minutes:21})){closeAll();render();toast('Demo time advanced. No activity was automatically completed.')}break;case'reset':reset();break;case'refresh':if(act('refresh')){go('find');toast('Fresh fictional listings. Your collection was preserved.')}break;case'share':open('share');break;case'copy-link':{const input=$('#share-url');if(navigator.clipboard)navigator.clipboard.writeText(input.value).then(()=>toast('Public prototype link copied. No private state.')).catch(()=>{input.select();toast('Select and copy this link.')});else{input.select();toast('Select and copy this link.')}break}
 case'area':filterDraft=copy(filters);open('filters');break;case'safety':open('safety',{id});break;case'block':{if(g?.members.includes(id))act('leave',{},false);if(act('block',{id})){go('find');toast('Blocked on this device. Shared group released.')}break}
}}
document.addEventListener('click',onAction);
document.addEventListener('input',e=>{if(e.target.id==='pop-query')pickerOptions(e.target.value);else if(e.target.id==='draft-note')draft.note=e.target.value;else if(e.target.id==='chat-input')$('#chat-form .send').disabled=!e.target.value.trim()});
document.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();if(act('chat',{text:$('#chat-input').value},false)){$('#chat-input').value='';$('#chat-form .send').disabled=true;drawMessages();$('#chat-input').focus()}}});
document.addEventListener('keydown',e=>{if(pop){if(e.key==='Escape'){e.preventDefault();e.stopPropagation();closePop();return}if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();pop.index=e.key==='Home'?0:e.key==='End'?pop.filtered.length-1:Math.max(0,Math.min(pop.filtered.length-1,pop.index+(e.key==='ArrowDown'?1:-1)));picker.querySelectorAll('.option').forEach((b,k)=>b.classList.toggle('kbd',k===pop.index));const option=$('#option-'+pop.index);option?.scrollIntoView({block:'nearest'});if($('#pop-query'))$('#pop-query').setAttribute('aria-activedescendant',option?.id||'');else option?.focus();return}if(e.key==='Enter'&&pop.index>=0){e.preventDefault();choose(pop.index);return}}if(e.key==='Escape'&&dialog.open){e.preventDefault();back()}});
document.addEventListener('pointerdown',e=>{if(pop&&!picker.contains(e.target)&&!pop.trigger?.contains(e.target))closePop()});
dialog.addEventListener('cancel',e=>{e.preventDefault();if(pop)closePop();else back()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeAll()}});
setInterval(()=>{C.sync(s);const m=Math.floor(C.now(s)/60000);if(m!==lastMinute){lastMinute=m;if(!dialog.open&&!pop){if(page==='find')drawList();else if(page==='group'&&document.activeElement?.id!=='chat-input')render()}save()}},1000);
window.RoundV5={version:C.VERSION,snapshot:()=>copy(s),dispatch:(type,d)=>act(type,d),reset,go,filters:()=>copy(filters)};
render();
})();
